functions.showToolManager:
function showToolManager() {
  var out = document.getElementById("output");
  out.innerHTML = "";
  out.classList.remove("hidden");
  out.classList.add("eli-view-enter");
  var header = createConfigHeader("ELI EXTENSIONS", "🧩", "Tool Manager", { marginBottom: "12px" });
  out.appendChild(header);
  var listWrap = document.createElement("div");
  listWrap.style.cssText = "padding:0 16px 16px 16px;";
  out.appendChild(listWrap);
  var actionsWrap = document.createElement("div");
  actionsWrap.style.cssText = "padding:0 16px 20px 16px; display:flex; gap:8px; flex-wrap:wrap;";
  out.appendChild(actionsWrap);
  if (typeof window.createPlatinumHomeBtn === "function") out.appendChild(window.createPlatinumHomeBtn());
  _toolManagerRender(listWrap, actionsWrap);
}

functions._toolManagerRender:
function _toolManagerRender(listWrap, actionsWrap) {
  // Mark wrappers so the auto-update badge refresher can find + re-render
  // this view if it's currently mounted.
  listWrap.setAttribute("data-tm-list", "1");
  actionsWrap.setAttribute("data-tm-actions", "1");
  listWrap.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading…</div>';
  Promise.all([loadFeatureData(STORE_JSON_TOOLS), _eliReadEnabledToolIds()]).then(function (results) {
    var rows = results[0] || [];
    var enabledIds = results[1];
    var tools = rows.filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    var meta = rows.filter(function (r) { return r && r.id === "__meta"; })[0];
    var sectionVer = (meta && Number(meta.version || meta.lastSeenVersion || 0)) || 0;
    function isEnabled(id) {
      if (enabledIds === null) return true;
      return enabledIds.indexOf(id) !== -1;
    }
    var enabledCount = tools.filter(function (t) { return isEnabled(t.id); }).length;
    var disabledCount = tools.length - enabledCount;
    var pending = window._eliPendingUpdates || [];
    var pendingById = {};
    pending.forEach(function (p) { pendingById[p.id] = p; });
    var available = window._eliAvailableTools || [];
    var availableById = {};
    available.forEach(function (a) { availableById[a.id] = a; });
    var installedById = {};
    tools.forEach(function (t) { installedById[t.id] = t; });
    var bundles = (window._eliBundles || []).slice();
    var updateCount = pending.length;
    var availableCount = available.length;
    function isMenuHidden(t) {
      var catId = (t.catalog && t.catalog.id) || "";
      if (typeof window._eliMenuItemHidden === "function") {
        return window._eliMenuItemHidden(catId, t.catalog || {});
      }
      var visOverride = "";
      try { visOverride = localStorage.getItem("eli_menuvis_" + catId) || ""; } catch (_) {}
      if (visOverride === "show") return false;
      if (visOverride === "hide") return true;
      return !!(t.catalog && t.catalog.hidden);
    }
    // ─── Bundle membership map ───────────────────────────────────────────
    var toolToBundles = {};
    bundles.forEach(function (b) {
      if (!Array.isArray(b.tools)) return;
      b.tools.forEach(function (toolId) {
        if (!toolToBundles[toolId]) toolToBundles[toolId] = [];
        toolToBundles[toolId].push(b.id);
      });
    });
    function inAnyBundle(toolId) { return !!toolToBundles[toolId]; }
    // ─── Filter state ─────────────────────────────────────────────────────
    var activeFilter = window._tmActiveFilter || "all";
    var hiddenCount = tools.filter(isMenuHidden).length;
    var adminCount = tools.filter(function (t) { return (t.catalog && t.catalog.category) === "Admin"; }).length;
    var standaloneTools = tools.filter(function (t) { return !inAnyBundle(t.id); });
    var filteredStandalone = standaloneTools.slice();
    if (activeFilter === "active") {
      filteredStandalone = filteredStandalone.filter(function (t) { return isEnabled(t.id); });
    } else if (activeFilter === "disabled") {
      filteredStandalone = filteredStandalone.filter(function (t) { return !isEnabled(t.id); });
    } else if (activeFilter === "updates") {
      filteredStandalone = filteredStandalone.filter(function (t) { return !!pendingById[t.id]; });
    } else if (activeFilter === "hidden") {
      filteredStandalone = filteredStandalone.filter(isMenuHidden);
    } else if (activeFilter === "admin") {
      filteredStandalone = filteredStandalone.filter(function (t) { return (t.catalog && t.catalog.category) === "Admin"; });
    }
    var byCategory = {};
    filteredStandalone.forEach(function (t) {
      var cat = (t.catalog && t.catalog.category) || "(uncategorized)";
      if (!byCategory[cat]) byCategory[cat] = [];
      byCategory[cat].push(t);
    });
    var categories = Object.keys(byCategory).sort(function (a, b) {
      if (a === "Tools - ELI Core") return -1;
      if (b === "Tools - ELI Core") return 1;
      if (a === "(uncategorized)") return 1;
      if (b === "(uncategorized)") return -1;
      return a.localeCompare(b);
    });
    var __fmtTmDate = function (val) {
      if (!val) return "";
      var d = new Date(typeof val === "number" ? val : String(val));
      if (isNaN(d.getTime())) return "";
      var mm = String(d.getMonth() + 1).padStart(2, "0");
      var dd = String(d.getDate()).padStart(2, "0");
      var yy = String(d.getFullYear()).slice(-2);
      return mm + "/" + dd + "/" + yy;
    };
    // ─── Header (count strip) ─────────────────────────────────────────────
    var bundleCount = bundles.length;
    var headerCount =
      '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; padding:6px 10px; background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff;">' +
      '<div style="font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' + tools.length + ' installed · ' + enabledCount + ' active' + (disabledCount > 0 ? ' · ' + disabledCount + ' disabled' : '') + (bundleCount > 0 ? ' · <span style="color:#c4b5fd;">' + bundleCount + ' bundle' + (bundleCount === 1 ? '' : 's') + '</span>' : '') + (updateCount > 0 ? ' · <span style="color:#fde68a;">' + updateCount + ' update' + (updateCount === 1 ? '' : 's') + '</span>' : '') + (availableCount > 0 ? ' · <span style="color:#86efac;">' + availableCount + ' new</span>' : '') + '</div>' +
      (sectionVer > 0 ? '<div style="font-size:10px; color:#94a3b8;">section v' + sectionVer + '</div>' : '') +
      '</div>';
    var html = headerCount;
    // ─── Filter chips (apply to standalone tools only) ────────────────────
    function chip(key, label, count, color) {
      if (count === 0 && key !== "all") return "";
      var active = activeFilter === key;
      var bg = active ? color : "#fff";
      var fg = active ? "#fff" : color;
      return '<button data-tm-filter="' + key + '" style="padding:5px 10px; font-size:10px; font-weight:700; cursor:pointer; background:' + bg + '; color:' + fg + '; border:1px solid ' + color + '; border-radius:0; letter-spacing:0.3px; text-transform:uppercase;">' + label + ' (' + count + ')</button>';
    }
    html += '<div style="display:flex; gap:5px; flex-wrap:wrap; margin-bottom:10px;">' +
