      var toggleBorder = on ? "#86efac" : "#cbd5e1";
      var visHidden = isMenuHidden(t);
      var visLabel = visHidden ? "🚫 Hidden" : "👁 In menus";
      var visBg = visHidden ? "#fff" : "#eef4ff";
      var visColor = visHidden ? "#94a3b8" : "#1e40af";
      var visBorder = visHidden ? "#cbd5e1" : "#bfdbfe";
      var visTitle = visHidden
        ? "Currently hidden from + menu and Customize Layout. Click to show."
        : "Currently shown in + menu and Customize Layout. Click to hide.";
      var updateRow = pendingForTool
        ? '<div style="background:#fffbeb; border-top:1px dashed #fcd34d; padding:6px 10px; margin:8px -12px -10px -12px; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
            '<div style="flex:1; min-width:0;">' +
              '<div style="font-size:10px; font-weight:800; color:#92400e; text-transform:uppercase; letter-spacing:0.5px;">🆙 v' + (ver || "?") + ' → v' + String(pendingForTool.version) + ' available</div>' +
              (pendingForTool.changelog ? '<div style="font-size:10px; color:#78350f; margin-top:2px;">' + _ebEsc(pendingForTool.changelog) + '</div>' : '') +
            '</div>' +
            '<button data-tm-update-cdn="' + _ebEsc(t.id) + '" title="Download v' + String(pendingForTool.version) + ' from CDN" style="padding:4px 12px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#f59e0b,#d97706); color:#fff; border:none; font-weight:800; border-radius:0;">UPDATE</button>' +
