        '<button data-tm-vis="' + _ebEsc(t.id) + '" title="' + visTitle + '" style="padding:4px 8px; font-size:10px; cursor:pointer; background:' + visBg + '; border:1px solid ' + visBorder + '; color:' + visColor + '; border-radius:0; font-weight:700;">' + visLabel + '</button>' +
        '<button data-tm-update="' + _ebEsc(t.id) + '" title="Upload a newer version (manual file)" style="padding:4px 8px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #1565c0; color:#1565c0; border-radius:0;">⬆️</button>' +
        '<button data-tm-export="' + _ebEsc(t.id) + '" title="Download as JSON" style="padding:4px 8px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #0d9488; color:#0d9488; border-radius:0;">📤</button>' +
        '<button data-tm-remove="' + _ebEsc(t.id) + '" title="Uninstall this tool" style="padding:4px 8px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #dc2626; color:#dc2626; border-radius:0;">🗑️</button>' +
