        '<div style="flex:1; min-width:0;">' +
        '<div style="font-size:12px; font-weight:700; color:#16a34a;">🌱 ' + _ebEsc(info.label) + ' <span style="font-size:10px; font-weight:500; color:#16a34a;">(v' + _ebEsc(String(info.version)) + ')</span></div>' +
        '<div style="font-size:9.5px; color:#64748b; margin-top:2px;">id: ' + _ebEsc(info.id) + ' · not installed yet</div>' +
        '</div>' +
        '<button data-tm-install-new="' + _ebEsc(info.id) + '" title="Install this member from CDN" style="padding:4px 12px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; font-weight:700; border-radius:0;">INSTALL</button>' +
        '</div>' +
        '</div>'
      );
    }
    // ─── BUNDLES section ──────────────────────────────────────────────────
    if (bundleCount > 0) {
      bundles.sort(function (a, b) {
        var ca = (a.category || "~").toLowerCase();
        var cb = (b.category || "~").toLowerCase();
        if (ca !== cb) return ca < cb ? -1 : 1;
        return (a.label || "").localeCompare(b.label || "");
      });
      html += '<div style="margin-top:6px; padding:6px 10px; background:linear-gradient(135deg,#4c1d95,#5b21b6); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
        '📦 Bundles (' + bundleCount + ')' +
