        var bLab = b.label || b.id;
        var bDesc = b.desc || "";
        var memberIds = Array.isArray(b.tools) ? b.tools : [];
        var dataIds = Array.isArray(b.data) ? b.data : [];
        var installedMemberIds = memberIds.filter(function (id) { return !!installedById[id]; });
        var pendingMemberIds = memberIds.filter(function (id) { return !!pendingById[id]; });
        var availableMemberIds = memberIds.filter(function (id) { return !installedById[id] && !!availableById[id]; });
        var missingMemberIds = memberIds.filter(function (id) { return !installedById[id] && !availableById[id]; });
