        html += '<details data-tm-bundle-key="' + _ebEsc(bundleKey) + '"' + (collapsed ? '' : ' open') + ' style="margin-bottom:8px; border:1px solid #c4b5fd; border-left:4px solid ' + bundleBorderColor + '; background:#faf5ff;">';
