            var lab = (dataInfo && dataInfo.label) || dataId;
            var stripe = mIdx % 2 === 0 ? "#fff" : "#f8fafc";
            var lock = dataId.indexOf("_proprietary") !== -1 ? ' 🔒' : '';
            if (verLocal && pendingById[dataId]) {
              // Installed but update available
              var pE = pendingById[dataId];
              html += '<div style="background:' + stripe + '; border:1px solid #fcd34d; border-left:3px solid #f59e0b; padding:8px 10px; margin-bottom:5px;">' +
                '<div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
                '<div style="flex:1; min-width:0;">' +
                '<div style="font-size:12px; font-weight:700; color:#92400e;">📚 ' + _ebEsc(lab) + lock + ' <span style="font-size:10px; color:#92400e;">(v' + _ebEsc(String(verLocal)) + ' → v' + _ebEsc(String(pE.version)) + ')</span></div>' +
                '<div style="font-size:9.5px; color:#78350f; margin-top:2px;">' + _ebEsc(dataId) + '</div>' +
                '</div>' +
                '<button data-tm-update-cdn="' + _ebEsc(dataId) + '" style="padding:4px 12px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#f59e0b,#d97706); color:#fff; border:none; font-weight:800;">UPDATE</button>' +
                '</div></div>';
            } else if (verLocal) {
              // Installed and current
              html += '<div style="background:' + stripe + '; border:1px solid #e2e8f0; border-left:3px solid #c4b5fd; padding:8px 10px; margin-bottom:5px;">' +
                '<div style="font-size:12px; font-weight:700; color:#0f172a;">📚 ' + _ebEsc(lab) + lock + ' <span style="font-size:10px; color:#5b21b6;">(v' + _ebEsc(String(verLocal)) + ' installed)</span></div>' +
                '<div style="font-size:9.5px; color:#94a3b8; margin-top:2px;">' + _ebEsc(dataId) + '</div>' +
                '</div>';
            } else if (availableById[dataId]) {
              // Available to install
              var aE = availableById[dataId];
              html += '<div style="background:' + stripe + '; border:1px solid #bbf7d0; border-left:3px solid #16a34a; padding:8px 10px; margin-bottom:5px;">' +
                '<div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
                '<div style="flex:1; min-width:0;">' +
                '<div style="font-size:12px; font-weight:700; color:#16a34a;">🌱📚 ' + _ebEsc(lab) + lock + ' <span style="font-size:10px;">(v' + _ebEsc(String(aE.version)) + ')</span></div>' +
                '<div style="font-size:9.5px; color:#64748b; margin-top:2px;">' + _ebEsc(dataId) + ' · not installed</div>' +
                '</div>' +
                '<button data-tm-install-new="' + _ebEsc(dataId) + '" style="padding:4px 12px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; font-weight:700;">INSTALL</button>' +
                '</div></div>';
            } else {
              // Missing from manifest (or audience-filtered out)
              html += '<div style="background:#fff; border:1px dashed #fca5a5; padding:8px 10px; margin-bottom:5px; font-size:10px; color:#991b1b;">' +
                '⚠️ ' + _ebEsc(lab) + ' (<code>' + _ebEsc(dataId) + '</code>) — not visible in your manifest' +
                '</div>';
            }
            mIdx++;
          });
        }
        html += '</div></details>';
      });
    }
    // ─── Standalone tools (not in any bundle), grouped by category ────────
    if (categories.length > 0) {
      html += '<div style="margin-top:14px; padding:6px 10px; background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
        (bundleCount > 0 ? '🧩 Standalone tools (' + filteredStandalone.length + ')' : '🧩 Tools (' + filteredStandalone.length + ')') +
        '</div>';
      categories.forEach(function (cat) {
        var catTools = byCategory[cat];
        var catEnabledCount = catTools.filter(function (t) { return isEnabled(t.id); }).length;
        var catKey = "eli_tm_cat_" + cat.replace(/\W+/g, "_");
        var collapsed = false;
        try { collapsed = localStorage.getItem(catKey) === "1"; } catch (_) {}
        if (activeFilter !== "all") collapsed = false;
        html += '<details data-tm-cat-key="' + _ebEsc(catKey) + '"' + (collapsed ? '' : ' open') + ' style="margin-bottom:8px; border:1px solid #cbd5e1;">';
        html += '<summary style="cursor:pointer; padding:7px 10px; background:linear-gradient(135deg,#1e3a8a,#1e40af); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; user-select:none; list-style:none; display:flex; justify-content:space-between; align-items:center;">' +
          '<span>' + _ebEsc(cat) + '</span>' +
          '<span style="opacity:0.78; font-weight:700;">' + catTools.length + ' · ' + catEnabledCount + ' active</span>' +
        '</summary>';
        html += '<div style="padding:8px;">';
        catTools.forEach(function (t, idx) { html += renderToolRow(t, idx); });
        html += '</div></details>';
      });
    } else if (bundleCount > 0 && tools.length > 0 && filteredStandalone.length === 0) {
      // All installed tools are in bundles, no standalone — only show this
      // hint when there's an active filter that excluded standalone entries.
      if (activeFilter !== "all") {
        html += '<div style="padding:14px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1; margin-top:10px;">' +
          'No standalone tools match the current filter.' +
          '</div>';
      }
    }
    // ─── Available to install (excluding members of any bundle) ───────────
    var unbundledAvailable = available.filter(function (a) { return !inAnyBundle(a.id); });
    if (unbundledAvailable.length > 0) {
      html +=
        '<div style="margin-top:14px; padding:6px 10px; background:linear-gradient(135deg,#064e3b,#065f46); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
        '🌱 Available to install (' + unbundledAvailable.length + ')' +
        '</div>';
      html += unbundledAvailable.map(function (a, idx) {
        var stripe = idx % 2 === 0 ? "#f0fdf4" : "#ecfdf5";
        return (
          '<div style="background:' + stripe + '; border:1px solid #bbf7d0; border-left:3px solid #16a34a; padding:10px 12px; margin-bottom:8px;">' +
          '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
          '<div style="flex:1; min-width:0;">' +
          '<div style="font-size:13px; font-weight:700; color:#0f172a;">🆕 ' + _ebEsc(a.label) + ' <span style="font-size:10px; font-weight:500; color:#16a34a;">(v' + _ebEsc(String(a.version)) + ')</span></div>' +
          '<div style="font-size:10px; color:#475569; margin-top:2px;">id: ' + _ebEsc(a.id) + (a.changelog ? ' · ' + _ebEsc(a.changelog) : '') + '</div>' +
          '</div>' +
          '<button data-tm-install-new="' + _ebEsc(a.id) + '" title="Install from CDN" style="padding:4px 14px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; font-weight:800; border-radius:0;">INSTALL</button>' +
          '</div>' +
          '</div>'
        );
      }).join("");
    }
    listWrap.innerHTML = html;
    // ─── Wire button handlers ─────────────────────────────────────────────
    listWrap.querySelectorAll("[data-tm-toggle]").forEach(function (b) {
      b.onclick = function () { _toolManagerToggle(b.getAttribute("data-tm-toggle"), listWrap, actionsWrap); };
    });
    listWrap.querySelectorAll("[data-tm-vis]").forEach(function (b) {
