    });
    listWrap.querySelectorAll("[data-tm-update]").forEach(function (b) {
      b.onclick = function () { _toolManagerUpdate(b.getAttribute("data-tm-update"), listWrap, actionsWrap); };
    });
    listWrap.querySelectorAll("[data-tm-export]").forEach(function (b) {
      b.onclick = function () { _toolManagerExport(b.getAttribute("data-tm-export"), tools); };
    });
