    });
    listWrap.querySelectorAll("[data-tm-bundle-update]").forEach(function (b) {
      b.onclick = function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (typeof _toolManagerUpdateBundle === "function") {
          _toolManagerUpdateBundle(b.getAttribute("data-tm-bundle-update"), listWrap, actionsWrap);
        }
