    // ─── Bottom action buttons ────────────────────────────────────────────
    actionsWrap.innerHTML = '';
    var btnInstall = document.createElement("button");
    btnInstall.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:1.5px solid #0d47a1; cursor:pointer;";
    btnInstall.innerHTML = "+ Install new tool(s) (file)";
    btnInstall.onclick = function () { _toolManagerInstall(null, listWrap, actionsWrap); };
    actionsWrap.appendChild(btnInstall);
    var btnExportSel = document.createElement("button");
    btnExportSel.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:#fff; color:#0d9488; border:1.5px solid #0d9488; cursor:pointer;";
    btnExportSel.innerHTML = "📦 Export selected as bundle";
    btnExportSel.onclick = function () { _toolManagerExportSelected(tools); };
    actionsWrap.appendChild(btnExportSel);
    var btnExportAll = document.createElement("button");
    btnExportAll.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:#f8fafc; color:#0d9488; border:1px solid #0d9488; cursor:pointer;";
