    btnExportAll.onclick = function () { _toolManagerExportAll(tools); };
    actionsWrap.appendChild(btnExportAll);
    var btnForceReinstall = document.createElement("button");
    btnForceReinstall.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:#fff; color:#d97706; border:1.5px solid #d97706; cursor:pointer;";
    btnForceReinstall.innerHTML = "🔄 Force reinstall…";
    btnForceReinstall.onclick = function () { _toolManagerForceReinstall(tools); };
    actionsWrap.appendChild(btnForceReinstall);
    if (updateCount > 0) {
      var btnAll = document.createElement("button");
      btnAll.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#f59e0b,#d97706); color:#fff; border:none; cursor:pointer; letter-spacing:0.5px;";
      btnAll.innerHTML = "🆙 Update all (" + updateCount + ")";
      btnAll.onclick = function () { _toolManagerApplyAllCdnUpdates(listWrap, actionsWrap); };
      actionsWrap.appendChild(btnAll);
    }
    if (availableCount > 0) {
      var btnInstallAll = document.createElement("button");
      btnInstallAll.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; cursor:pointer; letter-spacing:0.5px;";
      btnInstallAll.innerHTML = "🌱 Install all new (" + availableCount + ")";
      btnInstallAll.onclick = function () { _toolManagerInstallAllNew(listWrap, actionsWrap); };
      actionsWrap.appendChild(btnInstallAll);
    }
  });
}

functions._toolManagerUpdate:
function _toolManagerUpdate(toolId, listWrap, actionsWrap) {
  var inp = document.createElement("input");
  inp.type = "file"; inp.accept = ".json"; inp.style.display = "none";
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0]; if (!f) return;
    var reader = new FileReader();
    reader.onload = function (evt) {
      var json;
      try { json = JSON.parse(evt.target.result); }
      catch (err) { showToast("⚠️ Invalid JSON: " + (err && err.message ? err.message : "parse error"), "error"); return; }
      var arr = (json && json.sections && Array.isArray(json.sections.jsonTools)) ? json.sections.jsonTools : [];
      var match = arr.filter(function (t) { return t && t.id === toolId; })[0];
      if (!match) {
        showToast("⚠️ JSON doesn't contain a tool with id '" + toolId + "'", "error");
        return;
      }
      loadFeatureData(STORE_JSON_TOOLS).then(function (existing) {
        var byId = {};
        (existing || []).forEach(function (r) { if (r && r.id) byId[r.id] = r; });
        byId[toolId] = match;
        var rows = Object.keys(byId).map(function (k) { return byId[k]; });
        return saveFeatureData(STORE_JSON_TOOLS, rows);
      }).then(function () {
        if (typeof _dataHubSyncToolsToCatalog === "function") return _dataHubSyncToolsToCatalog();
      }).then(function () {
        if (typeof _eliLoadJsonTools === "function") _eliLoadJsonTools();
        showToast("✅ Tool updated: " + toolId, "success");
        _toolManagerRender(listWrap, actionsWrap);
      });
    };
    reader.readAsText(f);
  };
  document.body.appendChild(inp); inp.click();
  setTimeout(function () { try { document.body.removeChild(inp); } catch (_) { } }, 1000);
}

functions._toolManagerExport:
function _toolManagerExport(toolId, tools) {
  var t = tools.filter(function (x) { return x && x.id === toolId; })[0];
  if (!t) { showToast("Tool not found", "error"); return; }
  var payload = {
    schemaVersion: DATA_HUB_SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    sectionVersions: { jsonTools: Number(t.__version) || 1 },
    sections: { jsonTools: [t] },
  };
  var fname = "tool-" + toolId + "-" + new Date().toISOString().slice(0, 10) + ".json";
  _dataHubTriggerDownload(fname, JSON.stringify(payload, null, 2));
}

functions._toolManagerExportAll:
function _toolManagerExportAll(tools) {
  if (!tools.length) { showToast("No tools to export", "info"); return; }
  var maxVer = tools.reduce(function (m, t) { return Math.max(m, Number(t.__version) || 0); }, 0);
  var payload = {
    schemaVersion: DATA_HUB_SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    manifest: { name: "ELI Tool Bundle", count: tools.length },
    sectionVersions: { jsonTools: maxVer || 1 },
    sections: { jsonTools: tools },
  };
  var fname = "eli-tools-bundle-" + new Date().toISOString().slice(0, 10) + ".json";
  _dataHubTriggerDownload(fname, JSON.stringify(payload, null, 2));
}
// Per-tool checkbox dialog → exports the selection as a single bundle JSON.
// Lets you build a curated bundle (e.g. "DocuScrub + Final Review for Alice")
// without including every installed tool.

functions._toolManagerExportSelected:
function _toolManagerExportSelected(tools) {
  if (!tools.length) { showToast("No tools to export", "info"); return; }
  var rowsHtml = tools.map(function (t) {
    var ic = (t.catalog && t.catalog.icon) || "🧩";
    var lab = (t.catalog && t.catalog.title) || t.label || t.id;
    var cat = (t.catalog && t.catalog.category) || "Uncategorized";
    var ver = Number(t.__version) || 0;
    return '<label style="display:block; padding:7px 10px; cursor:pointer; border-bottom:1px solid #f1f5f9; text-align:left;">' +
      '<input type="checkbox" data-tm-exp-id="' + _ebEsc(t.id) + '" style="margin-right:8px; vertical-align:middle; cursor:pointer;">' +
      '<span style="font-size:12px; font-weight:700; color:#0f172a; vertical-align:middle;">' + ic + ' ' + _ebEsc(lab) + '</span>' +
      ' <span style="color:#1565c0; font-size:10px;">v' + ver + '</span>' +
      ' <span style="color:#64748b; font-size:10px;">· ' + _ebEsc(cat) + '</span>' +
    '</label>';
  }).join("");
  var bodyHtml =
    '<div style="font-size:11px; color:#64748b; margin-bottom:8px;">Select which tools to bundle into one JSON file.</div>' +
    '<div style="border:1px solid #e2e8f0; max-height:280px; overflow-y:auto; background:#fff;">' + rowsHtml + '</div>' +
    '<div style="margin-top:8px; display:flex; gap:8px; align-items:center; justify-content:flex-end; font-size:10px;">' +
    '<a href="#" data-tm-exp-all style="color:#1565c0; text-decoration:none; cursor:pointer;">All</a>' +
    '<a href="#" data-tm-exp-none style="color:#1565c0; text-decoration:none; cursor:pointer;">None</a>' +
    '</div>' +
    '<div style="margin-top:10px;">' +
    '<input type="text" id="tmExpBundleName" placeholder="Bundle name (optional, e.g. \'Alice Onboarding\')" style="width:100%; padding:7px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">' +
    '</div>';
  var ov = showEliDialog({
    variant: "info", textAlign: "left", icon: "📦", title: "Export selected as bundle",
    body: bodyHtml,
    buttons: [
      { id: "btnTmExpDo", label: "📦 Export bundle", passthrough: true,
        style: "flex:1; background:#0d9488; color:#fff; font-weight:800;",
        onclick: function () {
          var checked = ov.querySelectorAll('input[data-tm-exp-id]:checked');
          var ids = Array.prototype.map.call(checked, function (cb) { return cb.getAttribute("data-tm-exp-id"); });
          if (!ids.length) { showToast("Select at least one tool.", "info"); return; }
          var nameInput = ov.querySelector("#tmExpBundleName");
          var bundleName = (nameInput && nameInput.value && nameInput.value.trim()) || "ELI Tool Bundle";
          var subset = tools.filter(function (t) { return ids.indexOf(t.id) !== -1; });
          var maxVer = subset.reduce(function (m, t) { return Math.max(m, Number(t.__version) || 0); }, 0);
          var payload = {
            schemaVersion: DATA_HUB_SCHEMA_VERSION,
            exportedAt: new Date().toISOString(),
            manifest: { name: bundleName, count: subset.length, tools: subset.map(function (t) { return t.id; }) },
            sectionVersions: { jsonTools: maxVer || 1 },
            sections: { jsonTools: subset },
          };
          var slug = bundleName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "bundle";
          var fname = slug + "-" + new Date().toISOString().slice(0, 10) + ".json";
          _dataHubTriggerDownload(fname, JSON.stringify(payload, null, 2));
          showToast("📦 Exported " + subset.length + " tool(s) as " + fname, "success");
          ov.remove();
        } },
      { id: "btnTmExpCancel", label: "Cancel", passthrough: true, style: "flex:1; margin-left:5px;",
        onclick: function () { ov.remove(); } },
    ],
  });
  ov.querySelector('[data-tm-exp-all]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-exp-id]').forEach(function (cb) { cb.checked = true; });
  };
  ov.querySelector('[data-tm-exp-none]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-exp-id]').forEach(function (cb) { cb.checked = false; });
  };
}
// Force reinstall — manifest-driven picker. Fetches the live manifest so the
// list shows EVERY published entry (tools + data) with its current install
// state. User picks any → markers cleared → entries reappear as available
// in the next update check.
//   For tool kinds:  set json_tools row's __version → 0 AND clear releasedAt
//                    (so timestamp- and version-based detection both flag it)
//   For data kinds:  remove BOTH localStorage.eli_dataVer_<id> AND
//                    localStorage.eli_dataReleasedAt_<id>
// Does NOT delete IDB content — re-install merges over whatever's there.

functions._toolManagerForceReinstall:
function _toolManagerForceReinstall(installedTools) {
  var repo = window.ELI_UPDATE_REPO;
  var branch = window.ELI_UPDATE_BRANCH;
  var manifestName = window.ELI_UPDATE_MANIFEST;
  var GH_RAW_HOST = "raw.git" + "hubusercontent.com";
  var rawBlocked = false;
  try { rawBlocked = localStorage.getItem("eli_rawBlocked") === "1"; } catch (_) {}
  var ts = "?t=" + Date.now();
  var rawUrl = "https://" + GH_RAW_HOST + "/" + repo + "/" + branch + "/" + manifestName + ts;
  var cdnUrl = "https://cdn.jsdelivr.net/gh/" + repo + "@" + branch + "/" + manifestName + ts;
  var primaryUrl = rawBlocked ? cdnUrl : rawUrl;
  var fallbackUrl = rawBlocked ? null : cdnUrl;
  showToast("📥 Fetching manifest…");
  fetch(primaryUrl, { cache: "no-store" })
    .then(function (r) { if (!r.ok) throw new Error("manifest " + r.status); return r.json(); })
    .catch(function (e) {
      if (!fallbackUrl) throw e;
      return fetch(fallbackUrl, { cache: "no-store" }).then(function (r) {
        if (!r.ok) throw new Error("manifest " + r.status);
        return r.json();
      });
    })
    .then(function (mfst) { _tmShowFriPicker(mfst, installedTools); })
    .catch(function (e) {
      showToast("⚠️ Couldn't fetch manifest: " + (e.message || e), "error");
    });
}

functions._tmShowFriPicker:
function _tmShowFriPicker(mfst, installedTools) {
  var installedById = {};
  (installedTools || []).forEach(function (t) { if (t && t.id) installedById[t.id] = t; });
  var items = (mfst.tools || []).filter(function (m) {
    return m && m.kind !== "bundle"; // bundles are virtual — no install marker to reset
  }).map(function (m) {
    var kind = m.kind || "tool";
    var state = "", color = "#94a3b8", inst, ver;
    if (kind === "tool") {
      inst = installedById[m.id];
      if (!inst) { state = "⌀ not installed"; color = "#94a3b8"; }
      else if (typeof window._eliRemoteIsNewer === "function" && window._eliRemoteIsNewer(m, inst)) {
        state = "🆙 v" + String(inst.__version) + " → v" + String(m.version) + " (update available)"; color = "#d97706";
      } else { state = "✓ installed v" + String(inst.__version); color = "#16a34a"; }
    } else {
      ver = 0;
      try { ver = Number(localStorage.getItem("eli_dataVer_" + m.id)) || 0; } catch (_) {}
      if (ver === 0) { state = "⌀ not installed"; color = "#94a3b8"; }
      else if (ver >= Number(m.version)) { state = "✓ installed v" + ver; color = "#16a34a"; }
      else { state = "🆙 v" + ver + " → v" + m.version + " (update available)"; color = "#d97706"; }
    }
    return { id: m.id, kind: kind, label: m.label || m.id, category: m.category || "Uncategorized", state: state, color: color, confidential: !!m.confidential };
  });
  if (!items.length) { showToast("Manifest is empty.", "info"); return; }
  // ─── Group by BUNDLE first, with a fallback "Standalone" group for items
  // that aren't a member of any bundle. Within each group, items are listed
  // alphabetically. This mirrors Tool Manager's main render so users see
  // the same structure when force-reinstalling.
  var bundles = (mfst.tools || []).filter(function (m) { return m && m.kind === "bundle"; });
  var itemById = {}; items.forEach(function (it) { itemById[it.id] = it; });
  var inAnyBundle = {};
  bundles.forEach(function (b) {
    if (!Array.isArray(b.tools)) return;
    b.tools.forEach(function (toolId) { inAnyBundle[toolId] = true; });
  });
  // Build groups: one per bundle (members only) + "Standalone" (everything not in a bundle)
  var groups = bundles.map(function (b) {
    var members = (b.tools || []).map(function (id) { return itemById[id]; }).filter(Boolean);
    return {
      key: "bundle:" + b.id,
      label: (b.icon || "📦") + " " + (b.label || b.id),
      headerColor: "#5b21b6",
      headerBg: "linear-gradient(135deg,#4c1d95,#5b21b6)",
      items: members,
    };
  });
  var standalone = items.filter(function (it) { return !inAnyBundle[it.id]; });
  if (standalone.length > 0) {
    groups.push({
      key: "standalone",
      label: "🧩 Standalone (not in any bundle)",
      headerColor: "#1e3a8a",
      headerBg: "linear-gradient(135deg,#0f172a,#1e293b)",
      items: standalone,
    });
  }
  // Drop empty groups (bundle that lists tool ids not in the manifest)
  groups = groups.filter(function (g) { return g.items.length > 0; });
  var rowsHtml = groups.map(function (g) {
    var groupKey = "eli_tm_fri_grp_" + g.key.replace(/\W+/g, "_");
    var grpCollapsed = false;
    try { grpCollapsed = localStorage.getItem(groupKey) === "1"; } catch (_) {}
    var section =
      '<details data-tm-fri-grp="' + _ebEsc(groupKey) + '"' + (grpCollapsed ? '' : ' open') + ' style="border-bottom:1px solid #e2e8f0;">' +
        '<summary style="cursor:pointer; padding:6px 10px; background:' + g.headerBg + '; color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; user-select:none; list-style:none; display:flex; justify-content:space-between; align-items:center;">' +
          '<span>' + _ebEsc(g.label) + '</span>' +
          '<span style="opacity:0.78; font-weight:700;">' + g.items.length + ' tool' + (g.items.length === 1 ? '' : 's') + '</span>' +
        '</summary>' +
        '<div>';
    var rows = g.items.map(function (item) {
      var ic = item.kind === "tool" ? "🧩" : "📦";
      var lock = item.confidential ? ' <span style="font-size:11px; color:#7c2d12;" title="Confidential — encrypted distribution">🔒</span>' : '';
      return '<label style="display:block; padding:7px 10px; cursor:pointer; border-bottom:1px solid #f1f5f9; text-align:left;">' +
        '<input type="checkbox" data-tm-fri-kind="' + item.kind + '" data-tm-fri-id="' + _ebEsc(item.id) + '"' +
        (item.confidential ? ' data-tm-fri-confidential="1"' : '') +
        ' style="margin-right:8px; vertical-align:middle; cursor:pointer;">' +
        '<span style="font-size:12px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(item.label) + lock + '</span>' +
        '<div style="font-size:10px; color:' + item.color + '; margin:2px 0 0 24px;">' + item.state + '</div>' +
      '</label>';
    }).join("");
    return section + rows + '</div></details>';
  }).join("");
  var bodyHtml =
    '<div style="font-size:11px; color:#64748b; margin-bottom:8px; text-align:left;">' +
    'Reset install markers for selected items. They\'ll appear as <strong>available to install</strong> in the next update check. ' +
    'Existing IDB content is NOT deleted — re-install merges over it (no data loss).</div>' +
    '<div style="border:1px solid #e2e8f0; max-height:340px; overflow-y:auto; background:#fff;">' + rowsHtml + '</div>' +
    '<div style="margin-top:8px; display:flex; gap:8px; justify-content:flex-end; font-size:10px;">' +
    '<a href="#" data-tm-fri-proprietary style="color:#7c2d12; text-decoration:none; cursor:pointer; font-weight:700;">🔒 Proprietary</a>' +
    '<a href="#" data-tm-fri-all style="color:#1565c0; text-decoration:none; cursor:pointer;">All</a>' +
    '<a href="#" data-tm-fri-none style="color:#1565c0; text-decoration:none; cursor:pointer;">None</a>' +
    '</div>';
  var ov = showEliDialog({
    variant: "warning", textAlign: "left", icon: "🔄", title: "Force reinstall",
    body: bodyHtml,
    buttons: [
      { id: "btnTmFriDo", label: "🔄 Reset markers", passthrough: true,
        style: "flex:1; background:#d97706; color:#fff; font-weight:800;",
        onclick: function () {
          var checked = ov.querySelectorAll('input[data-tm-fri-id]:checked');
          if (!checked.length) { showToast("Select at least one.", "info"); return; }
          var dataIds = [], toolIds = [];
          Array.prototype.forEach.call(checked, function (cb) {
            var kind = cb.getAttribute("data-tm-fri-kind");
            var id = cb.getAttribute("data-tm-fri-id");
            if (kind === "data") {
              // Clear BOTH the version marker AND the timestamp marker so
              // update detection (which prefers timestamp comparison) flags
              // this as "available to install" again. Otherwise a leftover
              // eli_dataReleasedAt_<id> would suppress the prompt.
              try { localStorage.removeItem("eli_dataVer_" + id); } catch (_) {}
              try { localStorage.removeItem("eli_dataReleasedAt_" + id); } catch (_) {}
              dataIds.push(id);
            }
            else if (kind === "tool") { toolIds.push(id); }
          });
          var toolUpdates = toolIds.map(function (id) {
            return loadFeatureDataByIds(STORE_JSON_TOOLS, [id]).then(function (rows) {
              if (rows && rows[0]) {
                // Reset BOTH markers so update-detection (timestamp- or
                // version-based) flags this tool as "available to install"
                // regardless of which path the comparison takes.
                rows[0].__version = 0;
                rows[0].releasedAt = "";
                return saveFeatureRow(STORE_JSON_TOOLS, rows[0]);
              }
            });
          });
          Promise.all(toolUpdates).then(function () {
            ["eli_pendingUpdates", "eli_availableTools", "eli_updateNoticeSig", "eli_lastUpdateCheck"].forEach(function (k) {
              try { localStorage.removeItem(k); } catch (_) {}
            });
            showToast("✓ Reset " + (dataIds.length + toolIds.length) + " marker(s). Reload ELI to see them in install dialog.", "success");
            ov.remove();
          });
        } },
      { id: "btnTmFriCancel", label: "Cancel", passthrough: true, style: "flex:1; margin-left:5px;",
        onclick: function () { ov.remove(); } },
    ],
  });
  ov.querySelector('[data-tm-fri-all]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-fri-id]').forEach(function (cb) { cb.checked = true; });
  };
  ov.querySelector('[data-tm-fri-none]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-fri-id]').forEach(function (cb) { cb.checked = false; });
  };
  // Quick-select for confidential entries (encrypted proprietary libraries
  // with the lock 🔒 marker). Replaces existing selection — picks ONLY them.
  var propLink = ov.querySelector('[data-tm-fri-proprietary]');
  if (propLink) propLink.onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-fri-id]').forEach(function (cb) {
      cb.checked = cb.getAttribute('data-tm-fri-confidential') === '1';
    });
  };
  // Per-group collapse persistence
  ov.querySelectorAll('details[data-tm-fri-grp]').forEach(function (d) {
    d.addEventListener('toggle', function () {
      var key = d.getAttribute('data-tm-fri-grp');
      try { localStorage.setItem(key, d.open ? "0" : "1"); } catch (_) {}
    });
  });
}

functions._toolManagerInstall:
function _toolManagerInstall(_unused, listWrap, actionsWrap) {
  var inp = document.createElement("input");
  inp.type = "file"; inp.accept = ".json"; inp.style.display = "none";
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0]; if (!f) return;
    var reader = new FileReader();
    reader.onload = function (evt) {
      var json;
      try { json = JSON.parse(evt.target.result); }
      catch (err) { showToast("⚠️ Invalid JSON: " + (err && err.message ? err.message : "parse error"), "error"); return; }
      _dataHubImportFromJson(json, { allowedKeys: ["jsonTools"], actions: { jsonTools: "merge" } }).then(function (res) {
        if (res.ok) {
          showToast("✅ Installed " + (res.results[0] && res.results[0].rows ? res.results[0].rows : "?") + " tool(s)", "success");
          _toolManagerRender(listWrap, actionsWrap);
        } else {
          showToast("⚠️ Install errors: " + res.errors.join(", "), "error");
        }
      });
    };
    reader.readAsText(f);
  };
  document.body.appendChild(inp); inp.click();
  setTimeout(function () { try { document.body.removeChild(inp); } catch (_) { } }, 1000);
}
// Toggle whether a tool appears in the + Run Unpinned App dropdown and the
// Customize Layout "Available Apps" list. Per-tool override stored as
// localStorage["eli_menuvis_<catalogId>"] = "show" | "hide". Beats the catalog.hidden
// field and the hardcoded HIDDEN_FROM_DASHBOARD_MENU list. Doesn't disable the tool.

functions._toolManagerToggleVisibility:
function _toolManagerToggleVisibility(toolId, listWrap, actionsWrap) {
  loadFeatureDataByIds(STORE_JSON_TOOLS, [toolId]).then(function (rows) {
    var tool = rows && rows[0];
    if (!tool || !tool.catalog || !tool.catalog.id) {
      showToast("Tool has no catalog entry: " + toolId, "error");
      return;
    }
    var catId = tool.catalog.id;
    var key = "eli_menuvis_" + catId;
    // Determine current EFFECTIVE state via the same resolver the dashboard uses,
    // so a single click always flips to the opposite of what the user actually sees.
    var effHidden = false;
    if (typeof window._eliMenuItemHidden === "function") {
      effHidden = window._eliMenuItemHidden(catId, tool.catalog);
    } else {
      var current = "";
      try { current = localStorage.getItem(key) || ""; } catch (_) {}
      if (current === "show") effHidden = false;
      else if (current === "hide") effHidden = true;
      else effHidden = !!tool.catalog.hidden;
    }
    var next = effHidden ? "show" : "hide";
    try { localStorage.setItem(key, next); } catch (e) {
      showToast("Couldn't save preference: " + (e && e.message || e), "error");
      return;
    }
    if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache();
    if (typeof _eliEnsureCatalogLoaded === "function") {
      _eliEnsureCatalogLoaded().then(function () {
        try { if (typeof window.refreshDashboardGrid === "function") window.refreshDashboardGrid(); } catch (_) {}
      });
    }
    showToast(
      next === "show" ? "👁 Now shown in menus: " + (tool.catalog.title || toolId)
                      : "🚫 Hidden from menus: " + (tool.catalog.title || toolId),
      next === "show" ? "success" : "info"
    );
    _toolManagerRender(listWrap, actionsWrap);
  });
}

functions._toolManagerToggle:
function _toolManagerToggle(toolId, listWrap, actionsWrap) {
  Promise.all([
    loadFeatureDataByIds(STORE_JSON_TOOLS, ["__enabled"]),
    loadFeatureDataByIds(STORE_JSON_TOOLS, [toolId]),
  ]).then(function (results) {
    var enabledRow = (results[0] && results[0][0]) || null;
    var toolRow = (results[1] && results[1][0]) || null;
    if (!toolRow) { showToast("Tool not found: " + toolId, "error"); return; }
    var enabled = (enabledRow && Array.isArray(enabledRow.ids)) ? enabledRow.ids.slice() : null;
    var willEnable, newEnabled;
    if (enabled === null) {
      return loadFeatureData(STORE_JSON_TOOLS).then(function (allRows) {
        var ids = (allRows || [])
          .filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; })
          .map(function (r) { return r.id; });
        newEnabled = ids.filter(function (id) { return id !== toolId; });
        willEnable = false;
        return _tmApplyToggle(newEnabled, willEnable, toolRow);
      });
    }
    var idx = enabled.indexOf(toolId);
    if (idx === -1) { newEnabled = enabled.concat([toolId]); willEnable = true; }
    else { newEnabled = enabled.slice(0, idx).concat(enabled.slice(idx + 1)); willEnable = false; }
    return _tmApplyToggle(newEnabled, willEnable, toolRow);
  }).then(function () {
    _toolManagerRender(listWrap, actionsWrap);
  });
}

functions._tmApplyToggle:
function _tmApplyToggle(newEnabledIds, willEnable, toolRow) {
  var p = saveFeatureRow(STORE_JSON_TOOLS, { id: "__enabled", ids: newEnabledIds });
  if (willEnable && toolRow.functions) {
    try {
      Object.keys(toolRow.functions).forEach(function (fnName) {
        var src = toolRow.functions[fnName];
        if (typeof src === "string" && src.length) {
          window[fnName] = new Function("return (\n" + src + "\n);")();
        }
      });
    } catch (e) { if (typeof ELI_DEBUG !== "undefined" && ELI_DEBUG) console.warn("[ELI] toggle-enable eval error:", e); }
  }
  return p.then(function () {
    if (!toolRow.catalog || !toolRow.catalog.id) return;
    if (willEnable) {
      var catalogRow = Object.assign({}, toolRow.catalog, { source: "tool:" + toolRow.id });
      return saveFeatureRow(STORE_CATALOG, catalogRow);
    } else {
      return deleteFeatureRow(STORE_CATALOG, toolRow.catalog.id);
    }
  }).then(function () {
    if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache();
    if (typeof _eliEnsureCatalogLoaded === "function") {
      return _eliEnsureCatalogLoaded().then(function () {
        try { if (typeof window.refreshDashboardGrid === "function") window.refreshDashboardGrid(); } catch (_) {}
      });
    }
  }).then(function () {
    showToast(willEnable ? "✓ Enabled: " + toolRow.id : "🔕 Disabled: " + toolRow.id, willEnable ? "success" : "info");
  });
}

functions._toolManagerRemove:
function _toolManagerRemove(toolId, listWrap, actionsWrap) {
  var ovRm = showEliDialog({
    variant: "danger", icon: "🗑️", title: "Remove tool?",
    body: "This will uninstall <strong>" + _ebEsc(toolId) + "</strong> and remove its dashboard tile.<br><br>You can re-install it later by uploading the JSON.",
    buttons: [
      { id: "btnTmCancel", label: "Cancel", cls: "btn-platinum-config", style: "flex:1; margin-right:6px;",
        onclick: function () { ovRm.remove(); } },
      { id: "btnTmOk", label: "Remove", style: "flex:1; margin-left:6px; background:#dc2626; color:#fff; font-weight:bold;",
        onclick: function () {
          ovRm.remove();
          loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
