              return _dataHubCascadeRemoveToolCatalog([toolId]);
            }
          }).then(function () {
            showToast("🗑️ Removed: " + toolId, "success");
            _toolManagerRender(listWrap, actionsWrap);
          });
        } },
    ],
  });
}
// ─── Bundle bulk actions ──────────────────────────────────────────────
// "Update all" and "Install all" buttons on a bundle row run the existing
// per-tool flows (_toolManagerApplyCdnUpdate / _toolManagerInstallNew) over
// the bundle's member subset. Sequential, not parallel — the GH Contents
// API doesn't love bursty PUTs, and we want clean "X of Y" status toasts.

functions._toolManagerUpdateBundle:
function _toolManagerUpdateBundle(bundleId, listWrap, actionsWrap) {
  var bundles = window._eliBundles || [];
  var b = bundles.filter(function (x) { return x && x.id === bundleId; })[0];
  if (!b) { showToast("Bundle not found: " + bundleId, "error"); return; }
  var pending = window._eliPendingUpdates || [];
  var pendingIds = {};
  pending.forEach(function (p) { pendingIds[p.id] = true; });
  // Walk BOTH tool and data members — each pending entry id (tool or data)
  // is in pendingIds; the apply path handles each kind correctly.
  var allMemberIds = (Array.isArray(b.tools) ? b.tools : [])
    .concat(Array.isArray(b.data) ? b.data : []);
  var memberIds = allMemberIds.filter(function (id) { return pendingIds[id]; });
  if (!memberIds.length) {
    showToast("No pending updates in bundle.", "info");
    return;
  }
  showToast("🆙 Updating " + memberIds.length + " member" + (memberIds.length === 1 ? "" : "s") + " of " + (b.label || b.id) + "…", "info");
  // Sequential: chain promises so each completes before the next starts.
  var chain = Promise.resolve();
  memberIds.forEach(function (id) {
    chain = chain.then(function () {
      return new Promise(function (resolve) {
        // _toolManagerApplyCdnUpdate doesn't return a promise; it re-renders
        // on completion. We give each call a small delay between starts.
        try { _toolManagerApplyCdnUpdate(id, listWrap, actionsWrap); } catch (_) { }
        setTimeout(resolve, 1500);
      });
    });
  });
  chain.then(function () {
    showToast("✅ Bundle updates complete: " + (b.label || b.id), "success");
  });
}
// Uninstall every installed member of a bundle — both tool members and
// data members. Designed for the "switch group" use case: an admin moves a
// user from External Innovation → Patents by uninstalling the EI bundle
// then installing the Patents one. A confirmation dialog spells out impact.
//
// Tools shared with OTHER bundles the user can also see are still removed
// here — keep it predictable. The user can re-install them from the other
// bundle's row afterward if needed.

functions._toolManagerUninstallBundle:
function _toolManagerUninstallBundle(bundleId, listWrap, actionsWrap) {
  var bundles = window._eliBundles || [];
  var b = bundles.filter(function (x) { return x && x.id === bundleId; })[0];
  if (!b) { showToast("Bundle not found: " + bundleId, "error"); return; }
  var toolMemberIds = Array.isArray(b.tools) ? b.tools : [];
  var dataMemberIds = Array.isArray(b.data) ? b.data : [];
  // Filter to actually-installed members
  var ld;
  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var installedById = {};
    (rows || []).forEach(function (r) { if (r && r.id) installedById[r.id] = true; });
    var toolsToRemove = toolMemberIds.filter(function (id) { return installedById[id]; });
    var dataToReset = dataMemberIds.filter(function (id) {
      try { return !!localStorage.getItem("eli_dataVer_" + id); } catch (_) { return false; }
    });
    if (!toolsToRemove.length && !dataToReset.length) {
      showToast("No installed members to uninstall.", "info");
      return;
    }
    // Bundles this user CAN see, that ALSO contain any of these tools — informs
    // the user that some "uninstalled" members will reappear under another bundle.
    var sharedNotes = [];
    toolsToRemove.forEach(function (toolId) {
      var others = bundles.filter(function (ob) {
        return ob && ob.id !== bundleId && Array.isArray(ob.tools) && ob.tools.indexOf(toolId) !== -1;
      });
      if (others.length) {
        sharedNotes.push(toolId + " (also in: " + others.map(function (o) { return o.label || o.id; }).join(", ") + ")");
      }
    });
    var bodyHtml =
      '<div style="font-size:11px; color:#475569; line-height:1.5; text-align:left;">' +
      '<div style="margin-bottom:8px;">Uninstall all members of <strong style="color:#0f172a;">' + _ebEsc(b.label || b.id) + '</strong>?</div>' +
      (toolsToRemove.length
        ? '<div style="margin:6px 0;"><strong>🧩 Tools to remove (' + toolsToRemove.length + '):</strong><br>' +
            '<span style="font-family:ui-monospace,Consolas,monospace; font-size:10px; color:#dc2626;">' +
            toolsToRemove.map(_ebEsc).join(", ") + '</span></div>'
        : '') +
      (dataToReset.length
        ? '<div style="margin:6px 0;"><strong>📚 Data libraries to delete (' + dataToReset.length + '):</strong><br>' +
            '<span style="font-family:ui-monospace,Consolas,monospace; font-size:10px; color:#dc2626;">' +
            dataToReset.map(_ebEsc).join(", ") + '</span>' +
            '<div style="margin-top:4px; font-size:10px; color:#92400e;">⚠️ All rows in the corresponding IDB stores will be cleared — including any local edits. Re-install pulls fresh content from CDN.</div>' +
          '</div>'
        : '') +
      (sharedNotes.length
        ? '<div style="margin-top:8px; padding:6px 10px; background:#fffbeb; border-left:3px solid #f59e0b; font-size:10px; color:#78350f;">' +
            '<strong>Note:</strong> these members are also in other bundles you can see — they\'ll reappear there as "available to install":<br>' +
            sharedNotes.map(_ebEsc).join("<br>") +
          '</div>'
        : '') +
      '<div style="margin-top:8px; font-size:10px; color:#94a3b8;">Tool IDB rows + catalog tiles are permanently removed. Data library IDB stores are emptied. Cannot be undone — make a Data Hub export first if you want a backup.</div>' +
      '</div>';
    if (typeof showEliDialog !== "function") {
      if (!window.confirm("Uninstall " + (toolsToRemove.length + dataToReset.length) + " member(s) of " + (b.label || b.id) + "? Cannot be undone.")) return;
      doUninstall();
      return;
    }
    showEliDialog({
      variant: "warning", textAlign: "left", icon: "🗑️",
      title: "Uninstall bundle: " + (b.label || b.id),
      body: bodyHtml,
      buttons: [
        { id: "btnTmBundleUninstallCancel", label: "Cancel",
          style: "flex:1; background:#fff; border:1px solid #cbd5e1; color:#64748b;",
          onclick: function () {
            var btn = document.getElementById("btnTmBundleUninstallCancel");
            if (btn && btn.closest(".eli-overlay")) btn.closest(".eli-overlay").remove();
          },
        },
        { id: "btnTmBundleUninstallDo", label: "🗑️ Uninstall " + (toolsToRemove.length + dataToReset.length), passthrough: true,
          style: "flex:1; background:#dc2626; color:#fff; font-weight:800;",
          onclick: function () {
            var btn = document.getElementById("btnTmBundleUninstallDo");
            if (btn && btn.closest(".eli-overlay")) btn.closest(".eli-overlay").remove();
            doUninstall();
          },
        },
      ],
    });
    function doUninstall() {
      // 1) Remove tool members from STORE_JSON_TOOLS (atomic batch)
      // 2) Empty each data library's IDB stores + clear localStorage markers
      // 3) Bust update cache + re-render
      var toolWork = toolsToRemove.length === 0
        ? Promise.resolve()
        : loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
            var keep = (rows || []).filter(function (r) { return !(r && r.id && toolsToRemove.indexOf(r.id) !== -1); });
            return saveFeatureData(STORE_JSON_TOOLS, keep);
          }).then(function () {
            if (typeof _dataHubCascadeRemoveToolCatalog === "function") {
              return _dataHubCascadeRemoveToolCatalog(toolsToRemove);
            }
          });
      // Resolve which IDB store(s) each data library populates by walking
      // the eli_dataIdSections_<id> reverse map (set during install / ALP
      // push). For each section key, look up DATA_HUB_SECTIONS for the
      // matching IDB store name, then saveFeatureData([]) clears it.
      var storeClearJobs = [];
      var dhs = (typeof window.DATA_HUB_SECTIONS !== "undefined")
        ? window.DATA_HUB_SECTIONS
        : (typeof DATA_HUB_SECTIONS !== "undefined" ? DATA_HUB_SECTIONS : []);
      dataToReset.forEach(function (dataId) {
        var sectionKeys = [];
        try {
          var raw = localStorage.getItem("eli_dataIdSections_" + dataId) || "[]";
          sectionKeys = JSON.parse(raw);
        } catch (_) { sectionKeys = []; }
        if (!Array.isArray(sectionKeys)) sectionKeys = [];
        sectionKeys.forEach(function (k) {
          var sec = dhs.find(function (s) { return s && s.key === k; });
          if (sec && sec.store) {
            storeClearJobs.push(saveFeatureData(sec.store, []));
          }
        });
        // Clear install markers regardless of whether content delete succeeded.
        try { localStorage.removeItem("eli_dataVer_" + dataId); } catch (_) {}
        try { localStorage.removeItem("eli_dataReleasedAt_" + dataId); } catch (_) {}
        try { localStorage.removeItem("eli_dataIdSections_" + dataId); } catch (_) {}
        // Forward map (key → id) cleanup — walk all sectionKeys we just
        // cleared and remove any that pointed at this data id.
        sectionKeys.forEach(function (k) {
          try {
            if (localStorage.getItem("eli_sectionDataId_" + k) === dataId) {
              localStorage.removeItem("eli_sectionDataId_" + k);
            }
          } catch (_) {}
        });
      });
      // Bust update cache so next force-check sees the cleared markers.
      try {
        ["eli_lastUpdateCheck", "eli_pendingUpdates", "eli_availableTools", "eli_updateNoticeSig"].forEach(function (k) {
          try { localStorage.removeItem(k); } catch (_) {}
        });
        window._eliPendingUpdates = undefined;
        window._eliAvailableTools = undefined;
      } catch (_) {}
      Promise.all([toolWork].concat(storeClearJobs)).then(function () {
        // Invalidate caches that might hold deleted content (catalog,
        // loading msgs, etc.) so the dashboard re-fetches.
        try { if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache(); } catch (_) {}
        try { if (typeof _eliInvalidateLoadingMsgsCache === "function") _eliInvalidateLoadingMsgsCache(); } catch (_) {}
        showToast("✓ Uninstalled " + (toolsToRemove.length + dataToReset.length) + " member(s) of " + (b.label || b.id), "success");
        _toolManagerRender(listWrap, actionsWrap);
      }).catch(function (e) {
        showToast("❌ Uninstall failed: " + (e && e.message ? e.message : "unknown"), "error");
        _toolManagerRender(listWrap, actionsWrap);
      });
    }
  });
}

functions._toolManagerInstallBundle:
function _toolManagerInstallBundle(bundleId, listWrap, actionsWrap) {
  var bundles = window._eliBundles || [];
  var b = bundles.filter(function (x) { return x && x.id === bundleId; })[0];
  if (!b) { showToast("Bundle not found: " + bundleId, "error"); return; }
  var available = window._eliAvailableTools || [];
  var availableIds = {};
  available.forEach(function (a) { availableIds[a.id] = true; });
  // Walk BOTH tool and data members — install-new handles each correctly
  // based on the manifest entry's `kind`.
  var allMemberIds = (Array.isArray(b.tools) ? b.tools : [])
    .concat(Array.isArray(b.data) ? b.data : []);
  var memberIds = allMemberIds.filter(function (id) { return availableIds[id]; });
  if (!memberIds.length) {
    showToast("No installable members in bundle.", "info");
    return;
  }
  showToast("🌱 Installing " + memberIds.length + " member" + (memberIds.length === 1 ? "" : "s") + " of " + (b.label || b.id) + "…", "info");
  var chain = Promise.resolve();
  memberIds.forEach(function (id) {
    chain = chain.then(function () {
      return new Promise(function (resolve) {
        try { _toolManagerInstallNew(id, listWrap, actionsWrap); } catch (_) { }
        setTimeout(resolve, 1500);
      });
    });
  });
  chain.then(function () {
    showToast("✅ Bundle install complete: " + (b.label || b.id), "success");
  });
}

functions._toolManagerForceCheck:
function _toolManagerForceCheck(listWrap, actionsWrap) {
  if (!window._eliCheckForToolUpdates) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  if (typeof showToast === "function") showToast("🔄 Checking for updates…");
  window._eliCheckForToolUpdates({ force: true }).then(function () {
    _toolManagerRender(listWrap, actionsWrap);
  });
}

functions._toolManagerInstallNew:
function _toolManagerInstallNew(toolId, listWrap, actionsWrap) {
  var entry = (window._eliAvailableTools || []).filter(function (a) { return a.id === toolId; })[0];
  if (!entry) { showToast("No available entry for " + toolId, "info"); return; }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  if (typeof showToast === "function") showToast("⬇️ Installing " + entry.label + " v" + entry.version + "…");
  window._eliApplyToolUpdate(entry).then(function () {
    // Drop from available list (it's now installed)
    if (Array.isArray(window._eliAvailableTools)) {
      window._eliAvailableTools = window._eliAvailableTools.filter(function (a) { return a.id !== toolId; });
    }
    showToast("✅ Installed " + entry.label + " v" + entry.version, "success");
    _toolManagerRender(listWrap, actionsWrap);
  }).catch(function (e) {
    showToast("⚠️ Install failed: " + (e.message || e), "error");
  });
}

functions._toolManagerInstallAllNew:
function _toolManagerInstallAllNew(listWrap, actionsWrap) {
  var avail = (window._eliAvailableTools || []).slice();
  if (!avail.length) { showToast("Nothing to install.", "info"); return; }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  showToast("⬇️ Installing " + avail.length + " new tool(s)…");
  function next(i, ok, fail) {
    if (i >= avail.length) {
      showToast(fail.length ? ("⚠️ " + ok.length + " installed, " + fail.length + " failed") : ("✅ " + ok.length + " new tool(s) installed"), fail.length ? "error" : "success");
      _toolManagerRender(listWrap, actionsWrap);
      return;
    }
    var a = avail[i];
    window._eliApplyToolUpdate(a).then(function () {
      ok.push(a.id);
      if (Array.isArray(window._eliAvailableTools)) {
        window._eliAvailableTools = window._eliAvailableTools.filter(function (x) { return x.id !== a.id; });
      }
      next(i + 1, ok, fail);
    }, function (e) {
      console.error("[ELI] new install failed for", a.id, e);
      fail.push(a.id);
      next(i + 1, ok, fail);
    });
  }
  next(0, [], []);
}

functions._toolManagerApplyCdnUpdate:
function _toolManagerApplyCdnUpdate(toolId, listWrap, actionsWrap) {
  var pending = (window._eliPendingUpdates || []).filter(function (p) { return p.id === toolId; })[0];
  if (!pending) {
    showToast("No pending update for " + toolId, "info");
    return;
  }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  if (typeof showToast === "function") showToast("⬇️ Downloading " + toolId + " v" + pending.version + "…");
  window._eliApplyToolUpdate(pending).then(function () {
    showToast("✅ " + toolId + " updated to v" + pending.version, "success");
    _toolManagerRender(listWrap, actionsWrap);
  }).catch(function (e) {
    showToast("⚠️ Update failed: " + (e.message || e), "error");
  });
}

functions._toolManagerApplyAllCdnUpdates:
function _toolManagerApplyAllCdnUpdates(listWrap, actionsWrap) {
  var pending = (window._eliPendingUpdates || []).slice();
  if (!pending.length) { showToast("Nothing to update.", "info"); return; }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  showToast("⬇️ Updating " + pending.length + " tool(s)…");
  // Apply sequentially so each import completes before the next starts.
  // (Tool Manager updating itself is fine — the loader re-evals all functions
  //  including this one, but the in-flight loop variable references stay valid.)
  function next(i, ok, fail) {
    if (i >= pending.length) {
      showToast(fail.length ? ("⚠️ " + ok.length + " updated, " + fail.length + " failed") : ("✅ " + ok.length + " tool(s) updated"), fail.length ? "error" : "success");
      _toolManagerRender(listWrap, actionsWrap);
      return;
    }
    var p = pending[i];
    window._eliApplyToolUpdate(p).then(function () {
      ok.push(p.id);
      next(i + 1, ok, fail);
    }, function (e) {
      console.error("[ELI] update failed for", p.id, e);
      fail.push(p.id);
      next(i + 1, ok, fail);
    });
  }
  next(0, [], []);
}
